package app.nota.data.html

/**
 * The full HTML5 named character reference set (the WHATWG
 * table, 2,125 semicolon forms) plus a single-pass decoder for
 * named and numeric references.
 *
 * Decoding happens exactly once, where raw markup becomes
 * text — the note parser for stored content, the exporter for
 * the raw strings it still handles itself — and it never
 * double-decodes: "&amp;copy;" is the literal text "&copy;",
 * while "&copy;" is "©", exactly as a browser reads them.
 * Unknown names stay literal; numeric references outside the
 * Unicode range, and lone surrogates, become U+FFFD.
 *
 * The table is packed as name\u0001value pairs joined by
 * \u0002 (split across two constants to stay well under the
 * class-file string limit) and expanded into a map on first
 * use.
 */
object HtmlEntities {

    fun decode(value: String): String {
        if ('&' !in value) return value
        val out = StringBuilder(value.length)
        var i = 0
        while (i < value.length) {
            val amp = value.indexOf('&', i)
            if (amp < 0) {
                out.append(value, i, value.length)
                break
            }
            out.append(value, i, amp)
            // Numeric references are decoded with OR without
            // the trailing semicolon: HTML5 parses "&#58" in
            // text and attribute values alike, so a URL check
            // that only understood the semicolon form would
            // wave "javascript&#58alert(1)" through as an
            // unknown scheme while the browser navigates it
            // as javascript:. The digit run is consumed as far
            // as it is valid; one optional ';' after it goes too.
            if (value.getOrNull(amp + 1) == '#') {
                var j = amp + 2
                val hex = value.getOrNull(j).let { it == 'x' || it == 'X' }
                if (hex) j++
                val digitsStart = j
                while (j < value.length &&
                    (if (hex) isHexDigit(value[j]) else value[j].isDigit())
                ) {
                    j++
                }
                if (j > digitsStart) {
                    val code = value.substring(digitsStart, j)
                        .toIntOrNull(if (hex) 16 else 10)
                    out.append(codePointOrReplacement(code))
                    i = if (value.getOrNull(j) == ';') j + 1 else j
                    continue
                }
                // "&#" with no digits is not a reference; fall
                // through and let the named path leave it literal.
            }
            // The longest HTML5 name is 31 characters and a
            // numeric reference at most 10, so the closing ';'
            // — if this is a reference at all — sits within
            // the next 34 characters. The scan is bounded on
            // purpose: hunting through the whole remaining
            // suffix for every '&' would make ampersand-heavy
            // text (a long code block full of & operators)
            // quadratic to decode.
            var semi = -1
            val limit = minOf(value.length, amp + 35)
            var j = amp + 1
            while (j < limit) {
                val ch = value[j]
                if (ch == ';') {
                    semi = j
                    break
                }
                if (ch == '&') break
                j++
            }
            if (semi < 0) {
                out.append('&')
                i = amp + 1
                continue
            }
            val body = value.substring(amp + 1, semi)
            val decoded = decodeReference(body)
            if (decoded == null) {
                out.append('&')
                i = amp + 1
            } else {
                out.append(decoded)
                i = semi + 1
            }
        }
        return out.toString()
    }

    private fun decodeReference(body: String): String? {
        // Named references only: decode() intercepts every
        // numeric form (semicolon or not) before this is called.
        if (body.isEmpty()) return null
        if (!body.all { it.isLetterOrDigit() }) return null
        return BY_NAME[body]
    }

    private fun isHexDigit(ch: Char): Boolean =
        ch in '0'..'9' || ch in 'a'..'f' || ch in 'A'..'F'

    private fun codePointOrReplacement(code: Int?): String =
        if (code == null || code !in 1..0x10FFFF ||
            code in 0xD800..0xDFFF
        ) {
            "\uFFFD"
        } else {
            String(Character.toChars(code))
        }

    private val BY_NAME: Map<String, String> by lazy {
        val map = HashMap<String, String>(2200)
        for (entry in (PACKED_A + PACKED_B).split('\u0002')) {
            val cut = entry.indexOf('\u0001')
            if (cut > 0) map[entry.substring(0, cut)] = entry.substring(cut + 1)
        }
        map
    }

